import React, { useEffect, useState } from 'react';
import Select from 'react-select';
import logo from './touani_logo.svg';
import reiLoading from './rei-ayanami-nge.gif';
import './App.css';
import InfoFooter from "./components/InfoFooter.js";
import * as XLSX from 'xlsx';

/* Import codes in components */

/* In this case they are for each section
 * BrowserRouter on top, then Routes.
 * Route has the content below within an element "element={}"
 * In the content we have in order from top to buttom.
 * Party with Settings
 * InfoFooter for simple footer content
 * A new Route is used with a path in "/profile"
 * UserSevantList is in the new element
 * Each code gets define through conts such as region
 * Each set is done in SettingsMenu
 */

/* The Order I should have */
/* Start with a title of the page
 * Followed should be a text and a dropdown list
 * Have a dropdown list of each entry which should spawn selected info in the component below
 * The component below dropdown is the content that is the focus of this page
 * If nothing is selected (in order): Display a picture of a random crossover image with some description, which should be ready as the page load
 * If a series is selected (in order): Spawn a title, a rectangular banner, a group of images of crossovers, a group of images of cameos on other series, a group of images of cameos in the series 
 * Each image in the groups should have a description on which character, series and source
 * There should be max 3-4 images per row depending on their size
 * (Not recommended) Videos may be included depending on how its being presented
 * A simple footer should be added at the end with contact lists
 */


/* Party code */
/* Import useState and css with the same name
 * Import code from the same folder and then fetch from Data
 * It's all about organizing your stuff
 * Can you host all of the images with appropriate names in a service that has api?
 * Imgur? Wordpress? Google Drive?
 * Check the community about APIs
 * Can we sort out the files with name convention like?
 * Anyway we make a const of Party which we export default later
 * In the Party const, we use ({formData, region}) and start by using a new const called servant
 * servant is a class that is populated with id, name, icon, className & rarity.
 * If we are going with crossover images, it will be seriesName, showsName, level & description.
 * Look at the turn google sheets into API
 * This if only we can't make a Backend on GitHub
 */

function App() {
 	
  // State to keep track of which div is shown
  const [selectedDiv, setSelectedDiv] = useState(null);
  const [disabled, setDisabled] = useState(false);
  const [loading, setLoading] = useState(false);
  
  const [data, setData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [cameosFrom, setCameosFrom] = useState([]);
  const [cameosTo, setCameosTo] = useState([]);
  
  const selectSeries = [
	{
		label: "Hokuto No Ken",
		value: "hokuto no ken",
		aliases: ["Fist of the North Star", "北斗の拳"]
	},
	{
		label: "Vampire Hunter D",
		value: "vampire hunter d",
		aliases: ["Vampire Hunter D", "吸血鬼ハンターD"]
	}
  ];
  
  useEffect(() => {

    fetch('xlsxFiles/Crossover_Cameos_in_Anime_Evidence_List_Only.xlszzx')
      .then(res => res.arrayBuffer())
      .then(arrayBuffer => {
        const workbook = XLSX.read(arrayBuffer, { type: 'array' });
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const allData = XLSX.utils.sheet_to_json(sheet, { header: 1 });
		const allDefaultLinkData = Object.entries(sheet)
										.filter(([key]) => key.startsWith("E"))
										.map(([_, value]) => value)
										.map(item => item.l)
										.filter(lValue => lValue !== undefined);
		const findTheGuilty = Object.entries(sheet)
										.filter(([key]) => key.startsWith("E"))
										.map(([_, value]) => value)
										.map(item => Object.keys(item).length);
										
		const allCommentsLinkData = Object.entries(sheet)
										.filter(([key]) => key.startsWith("G"))
										.map(([_, value]) => value)
										.map(item => item.l)
										.filter(lValue => lValue !== undefined);
		
		
        const [headerRow,...dataRows] = allData;
		
		dataRows.map((item, index) => { const addLink = allDefaultLinkData[index]?.Target ?? null; return item.push(addLink);});

		console.log("sheet:",sheet);
		console.log("dataRows:",dataRows);
		console.log("findTheGuilty:", findTheGuilty);
		console.log("allDefaultLinkData:", allDefaultLinkData);
		console.log("allCommentsLinkData:", allCommentsLinkData);
		
        setHeaders(headerRow);
        setData(dataRows);
      })
      .catch(err => console.error('Kunde inte ladda Excel-filen:', err));
  }, []);

  const handleSelectChange = (optionSelected) => {
	setLoading(true);
	setDisabled(true);
	  
    const name = optionSelected.label;

    if (name) {
      const nameIndex =  [headers.indexOf('Series'), headers.indexOf('from what series?')];
      setCameosFrom(data.filter(row => row[nameIndex[0]] === name));
	  setCameosTo(data.filter(row => row[nameIndex[1]] === name));
    }
	
	setLoading(false);
	setDisabled(false);
  };
  
  const customFilter = (option, inputValue) => {
	  const search = inputValue.toLowerCase();
	  const labelMatch = option.label.toLowerCase().includes(search);
	  const aliasMatch = option.data.aliases?.some(alias => alias.toLowerCase().includes(search));
	  
	  return labelMatch || aliasMatch;
  }
  
  return (
    <div className="App">
      <header className="App-header">
        <img src={logo} className="App-logo" alt="logo" />
        <p>
          Edit <code>src/App.js</code> and save to reload. 40
        </p>
			<label htmlFor="dropdown">Choose your series:</label>
			<Select id="dropdown" options={selectSeries} onChange={(options) => {setSelectedDiv(options); handleSelectChange(options);}}
			placeholder="Search..."  fontSize="13px" isClearable
			filterOption={customFilter} disabled={disabled}
			/>

		<div>

			{loading && selectedDiv && cameosFrom.length > 0 && (<> <img src={reiLoading} alt={"Loading..."} /> <p>Loading...</p></>)}
			{selectedDiv && cameosFrom.length > 0 && (
				<div style={{ marginTop: "20px" }}>
					<h3>`Cameos in ${selectedDiv.label}`</h3>
					<div style={{display: "flex", flexWrap: "wrap", gap: "10px" }}>
						{cameosFrom.map((url,idx) => (<>
						<div>
							<img
							key={idx}
							src={url[8]}
							alt={`${url[1]} in ${url[0]} ${url[4]}`}
							style={{maxWidth: "200px", borderRadius: "4px" }}
							/>
							<h6>{`${url[1]} in ${url[0]} ${url[4]}`}</h6>
							</div>
							</>
						))}
					</div>
				</div>
			)}
			{selectedDiv && cameosTo.length > 0 && (
				<div style={{ marginTop: "20px" }}>
					<h3>`Cameos of ${selectedDiv.label} characters`</h3>
					<div style={{display: "flex", flexWrap: "wrap", gap: "10px" }}>
						{cameosTo.map((url,idx) => (<>
						<div>
							<img
							key={idx}
							src={url[8]}
							alt={`${url[1]} in ${url[0]} ${url[4]}`}
							style={{maxWidth: "200px", borderRadius: "4px" }}
							/>
							<h6>{`${url[1]} in ${url[0]} ${url[4]}`}</h6>
							</div>
							</>
						))}
					</div>
				</div>
			)}

		</div>
	  </header>
	<InfoFooter />
    </div>
  );
}

export default App;
